// 简化版 useState 实现（仅演示核心原理）
let workInProgressHook = null;
let isMount = true;
let fiber = { memoizedState: null }; // 当前 Fiber 节点

function useState(initialValue) {
  let hook;
  if (isMount) {
    // mount：创建 Hook 节点，串入 Fiber 链表
    hook = { memoizedState: initialValue, queue: { pending: null }, next: null };
    if (!fiber.memoizedState) {
      fiber.memoizedState = hook;       // 第一个 Hook
    } else {
      workInProgressHook.next = hook;   // 追加到链表尾部
    }
    workInProgressHook = hook;
  } else {
    // update：按顺序取出对应 Hook
    hook = workInProgressHook;
    workInProgressHook = workInProgressHook.next;
  }

  // 处理更新队列（环形链表）
  let baseState = hook.memoizedState;
  if (hook.queue.pending) {
    let firstUpdate = hook.queue.pending.next; // 环形链表头
    do {
      const action = firstUpdate.action;
      baseState = typeof action === 'function' ? action(baseState) : action;
      firstUpdate = firstUpdate.next;
    } while (firstUpdate !== hook.queue.pending.next);
    hook.queue.pending = null;
  }
  hook.memoizedState = baseState;
  return [baseState, dispatchAction.bind(null, hook.queue)];
}

// dispatch 入队更新，触发调度
function dispatchAction(queue, action) {
  const update = { action, next: null };
  if (!queue.pending) {
    update.next = update; // 自引用形成环
  } else {
    update.next = queue.pending.next;
    queue.pending.next = update;
  }
  queue.pending = update;
  // 真实实现中这里调用 scheduleUpdateOnFiber 触发重渲染
}

// ---- 闭包陷阱示例 ----
function Counter() {
  const [count, setCount] = useState(0);

  // 错误：count 被闭包捕获，永远是 0
  useEffect(() => {
    const timer = setInterval(() => {
      setCount(count + 1); // stale closure!
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // 正确：函数式更新读取最新 baseState
  useEffect(() => {
    const timer = setInterval(() => {
      setCount(prev => prev + 1); // 不依赖闭包
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // 正确：声明依赖，依赖变化时重建 effect
  useEffect(() => {
    document.title = `Count: ${count}`;
  }, [count]);
}
